from pyspark.sql.types import *
from pyspark.ml.feature import QuantileDiscretizer
import pandas as pd
import time
from itertools import chain
from datetime import datetime, timedelta

import sys
from support_function import *


def main(argv=None):
    """Job entry point (design plan section 5.1, T1). Parameters: none."""
    spark = (SparkSession
                .builder
                .appName('recommendation_system')
                .config('spark.driver.memory', '188g') #'63g'
                .config('spark.executor.cores', '8') #'5'
                .config('spark.executor.instances', '11') #'28'
                .config('spark.executor.memory', '64g') #'125g'
                .config('spark.dynamicAllocation.enabled', 'false')
                .config('spark.dynamicAllocation.maxExecutors', '15')
                .config('spark.debug.maxToStringFields', "100")
                .config("spark.driver.memoryOverhead", '8192')
                .config("spark.executor.memoryOverhead", '8192')
                .config("spark.network.timeout", '800')
                .config("spark.yarn.queue", "root.hdp_ds")
                .config("spark.sql.legacy.allowCreatingManagedTableUsingNonemptyLocation", "true")
                .getOrCreate())

    sc = spark.sparkContext
    sys.path.insert(0, './recommendation_system/script/')
    today = getConfig('core', 'today')
    today = datetime.strptime(today, '%Y-%m-%d')
    day = getConfig('core', 'day')
    dt_pr = today - timedelta(days=day)
    max_date = dt_pr.strftime('%Y-%m-%d')
    dt_pr = dt_pr.strftime('%Y%m%d')

    queries = "SELECT cif_number, flag_simobi, active_flag FROM {}.{} WHERE partition_date = '{}'".format('mldb', 'mii_rs_customers', today.strftime('%Y-%m-%d'))
    df_customer = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_customers (K7 tables, K4-TBL-004)
    df_customer = df_customer.drop_duplicates()

    cif_customers = df_customer.select('cif_number').repartition('cif_number')

    trans_cols = getConfig('rfm_data_preprocessing', 'transaction_cols')
    queries = "SELECT {} FROM {}.{}".format(','.join(trans_cols), "dm_analytics", "dm_transaction_daily")
    dm_transaction = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.dm_transaction_daily (K7 tables, K4-TBL-004)

    dm_transaction = dm_transaction.withColumn("transaction_real_date", F.to_date(F.col("transaction_real_date"), 'yyyyMMdd'))
    dm_transaction = dm_transaction.withColumn("transaction_real_date", F.col("transaction_real_date").cast('string'))

    dm_transaction = dm_transaction.filter(F.col('transaction_real_date') <= max_date)

    # filter out records by scares by list 1
    l = ['null']
    dm_transaction = dm_transaction.filter(~dm_transaction.type_transaction_desc.isin(l))
    dm_transaction = dm_transaction.filter(F.col('type_transaction_desc').isNotNull())

    #Debit
    cond = [dm_transaction['receiver_cif'] == cif_customers['cif_number']]
    debit_transaction = dm_transaction.join(cif_customers, cond, how='inner')
    debit_transaction = debit_transaction.drop('cif_number')
    debit_transaction = debit_transaction.dropDuplicates()

    #Credit
    cond = [dm_transaction['sender_cif'] == cif_customers['cif_number']]
    credit_transaction = dm_transaction.join(cif_customers, cond, how='inner')
    credit_transaction = credit_transaction.drop('cif_number')
    credit_transaction = credit_transaction.dropDuplicates()

    debit_transaction = debit_transaction.withColumnRenamed('receiver_cif', 'cif_number')
    debit_transaction = debit_transaction.drop('sender_cif')

    credit_transaction = credit_transaction.withColumnRenamed('sender_cif', 'cif_number')
    credit_transaction = credit_transaction.drop('receiver_cif')

    transaction = debit_transaction.unionByName(credit_transaction)

    #emoney transaction
    tr_cols = getConfig('rfm_data_preprocessing', 'em_transaction_cols')
    queries = "SELECT {} FROM dm_analytics.em_finance_transaction WHERE dt_pr='{}'".format(', '.join(tr_cols), dt_pr)
    em_transaction = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.em_finance_transaction (K7 tables, K4-TBL-004)
    em_transaction = em_transaction.drop_duplicates()

    sts_cols = ['id', 'name']
    queries = "SELECT {} FROM dm_analytics.em_status WHERE dt_pr='{}'".format(', '.join(sts_cols), dt_pr)
    em_status = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for dm_analytics.em_status (K7 tables, K4-TBL-004)

    cond = [em_transaction['status'] == em_status['id']]
    em_transaction = em_transaction.join(F.broadcast(em_status), cond, how='left')
    em_transaction = em_transaction.drop('status', 'id')
    em_transaction = em_transaction.withColumnRenamed('name', 'status')

    em_transaction = em_transaction.filter((F.col('status') == 'Success') &
                                           (F.col('currency') == 'IDR'))

    em_transaction = em_transaction.drop('status', 'currency')
    em_transaction = em_transaction.withColumn('transaction_date',
                                               F.to_date(F.col('transaction_date'),
                                                         'yyyy/MM/dd HH:mm:ss').cast('string'))

    em_transaction = em_transaction.filter(F.col('transaction_date')>='2020-03-09')

    queries = "select account_id, cif_number from mldb.mii_rs_emoney where partition_date='{}'".format(today.strftime('%Y-%m-%d'))
    em_customer = spark.sql(queries)  # OPEN / TO BE VALIDATED: Unity Catalog names for mldb.mii_rs_emoney (K7 tables, K4-TBL-004)

    cond = [em_transaction['debit_account'] == em_customer['account_id']]
    debit_em_transaction = em_transaction.join(em_customer, cond, how='inner')
    debit_em_transaction = debit_em_transaction.drop('account_id')

    cond = [em_transaction['credit_account'] == em_customer['account_id']]
    credit_em_transaction = em_transaction.join(em_customer, cond, how='inner')
    credit_em_transaction = credit_em_transaction.drop('account_id')

    em_transaction = debit_em_transaction.unionByName(credit_em_transaction)
    em_transaction = em_transaction.drop_duplicates()

    em_transaction = em_transaction.withColumnRenamed('transaction_number', 'ft_number')
    em_transaction = em_transaction.withColumn('amount', F.col('transaction_amount')+F.col('charge_amount'))
    em_transaction = em_transaction.drop('credit_account', 'debit_account', 'transaction_amount', 'charge_amount')

    transaction = transaction.drop('sender_account', 'receiver_account', 'type_transaction_desc')
    transaction = transaction.withColumnRenamed('transaction_real_date', 'transaction_date')
    transaction = transaction.unionByName(em_transaction)
    transaction = transaction.repartition('cif_number')

    customer_rfm = transaction.groupby("cif_number").agg(
        F.count("ft_number").alias("frequency"),
        F.max("transaction_date").alias("last_transaction"),
        F.sum("amount").alias("monetary")).orderBy(["frequency"], ascending=False)

    customer_rfm = customer_rfm.withColumn('recency', F.datediff(F.current_date(), customer_rfm['last_transaction']))
    customer_rfm = customer_rfm.withColumn("recency", customer_rfm['recency'].cast('bigint'))
    customer_rfm = customer_rfm.drop('last_transaction')

    # RFM Score
    column = ['recency', 'frequency', 'monetary']
    for c in column:
        fpath = getConfig('prediction', c+'_bucketizer_fpath', sc)
        bucketizer = QuantileDiscretizer.load(fpath)
        customer_rfm = bucketizer.transform(customer_rfm)

    c = 'recency'
    customer_rfm = customer_rfm.withColumn(c+'_score', F.col(c+'_score')+1)
    customer_rfm = customer_rfm.withColumn(c+'_score', F.col(c+'_score').cast('int').cast('string'))

    mapping = {0:'4', 1:'3', 2:'2', 3:'1'}
    mapping_expr = F.create_map([F.lit(x) for x in chain(*mapping.items())])

    for c in ['frequency', 'monetary']:
        customer_rfm = customer_rfm.withColumn(c+'_score', F.col(c+'_score').cast('int'))
        customer_rfm = customer_rfm.withColumn(c+'_score', mapping_expr.getItem(F.col(c+'_score')))

    customer_rfm = customer_rfm.withColumn('rfm', F.concat(F.col('recency_score'),
                                                           F.col('frequency_score'), F.col('monetary_score')))

    customer_rfm = customer_rfm.withColumn('rfm_description', F.col('rfm'))

    customer_rfm = customer_rfm.withColumn('rfm_description', F.when(F.col('rfm_description') == '111',
                                                                     'best customers').otherwise(F.col('rfm_description')))

    customer_rfm = customer_rfm.withColumn('rfm_description', F.when(F.col('rfm_description') == '311',
                                                                     'almost lost').otherwise(F.col('rfm_description')))

    customer_rfm = customer_rfm.withColumn('rfm_description', F.when(F.col('rfm_description') == '411',
                                                                     'lost customers').otherwise(F.col('rfm_description')))

    customer_rfm = customer_rfm.withColumn('rfm_description', F.when(F.col('rfm_description') == '444',
                                                                     'lost cheap customers').otherwise(F.col('rfm_description')))

    customer_rfm = customer_rfm.withColumn('rfm_description',
                                           F.when(F.col('rfm_description').like('1%'),
                                                  'recent customers').otherwise(F.col('rfm_description')))
    customer_rfm = customer_rfm.withColumn('rfm_description',
                                           F.when(F.col('rfm_description').like('_1_'),
                                                  'loyal customers').otherwise(F.col('rfm_description')))
    customer_rfm = customer_rfm.withColumn('rfm_description',
                                           F.when(F.col('rfm_description').like('%1'),
                                                  'big deposit').otherwise(F.col('rfm_description')))
    customer_rfm = customer_rfm.withColumn('rfm_description',
                                           F.when(F.length('rfm_description') == 3,
                                                  'others').otherwise(F.col('rfm_description')))

    customer_rfm = customer_rfm.withColumn('partition_date', F.lit(today.strftime('%Y-%m-%d')))

    writeData(customer_rfm, spark, 'mldb', 'mii_rs_customer_rfm', partition='partition_date')

    pass  # removed by ws4conv (K4-SPK-006): do not stop the shared session on Databricks
    pass  # removed by ws4conv (K4-SPK-006): do not stop the shared session on Databricks


if __name__ == "__main__":
    main(sys.argv[1:])
